class Sum {
  public int calcSum(int num) {
    int sum;
    sum = 0;
    while (0 < num) {
      if (sum < 100) {
        sum = sum + num;
      } else {
      }
      num = num - 1;
    }
    return sum;
  }
}

public class Factorial{
    public static void main(String[] a){
	System.out.println(new Fac().ComputeFac(10));
    }
}

class Fac {

    public int ComputeFac(int num){
	int num_aux ;
	if (num < 1)
	    num_aux = 1 ;
	else 
	    num_aux = num * (this.ComputeFac(num-1)) ;
	return num_aux ;
    }

}
